var convertToBase7 = function(num) {
    if (num === 0) return "0";
    let neg = num < 0;
    let n = Math.abs(num);
    let digits = [];
    while (n > 0) {
        digits.push(n % 7);
        n = Math.floor(n / 7);
    }
    return (neg ? "-" : "") + digits.reverse().join("");
};

